#pragma once
#include "core/IO.h"
#include <opencv2/imgproc.hpp>
namespace ar::examples {
// Synthetic Android-like UI generated by code; independent of game screenshots.
inline ar::core::Result<void> make_demo(const std::filesystem::path &directory) {
    try {
        std::filesystem::create_directories(directory);
        cv::Mat before(360, 640, CV_8UC3, cv::Scalar(24, 24, 24)),
            after(360, 640, CV_8UC3, cv::Scalar(24, 24, 24));
        cv::RNG random(117);
        cv::Mat button(48, 120, CV_8UC3), done(48, 120, CV_8UC3);
        random.fill(button, cv::RNG::UNIFORM, 0, 255);
        random.fill(done, cv::RNG::UNIFORM, 0, 255);
        cv::putText(button, "OPEN", {15, 32}, cv::FONT_HERSHEY_SIMPLEX, 0.7, {255, 255, 255}, 2);
        cv::putText(done, "READY", {9, 32}, cv::FONT_HERSHEY_SIMPLEX, 0.7, {255, 255, 255}, 2);
        button.copyTo(before(cv::Rect(260, 156, 120, 48)));
        done.copyTo(after(cv::Rect(260, 156, 120, 48)));
        cv::putText(before, "ANDROID DEMO", {30, 60}, cv::FONT_HERSHEY_SIMPLEX, 1, {220, 220, 220}, 2);
        cv::putText(after, "DESTINATION", {30, 60}, cv::FONT_HERSHEY_SIMPLEX, 1, {220, 220, 220}, 2);
        for (const auto &item : std::vector<std::pair<const wchar_t *, cv::Mat>>{{L"before.png", before},
                                                                                 {L"after.png", after},
                                                                                 {L"open.png", button},
                                                                                 {L"ready.png", done}}) {
            auto written = ar::core::write_image(directory / item.first, item.second);
            if (!written)
                return written;
        }
        auto write = [&](const wchar_t *name, const char *data) {
            std::ofstream file(directory / name, std::ios::binary);
            if (!file || !(file << data))
                throw std::runtime_error("Cannot write demo JSON");
        };
        write(
            L"manifest.json",
            R"({"schema_version":1,"name":"android-navigation-demo","version":"1.0.0","reference_size":[640,360],"pipeline":"pipeline.json","templates":{"open":"open.png","ready":"ready.png"}})");
        write(
            L"pipeline.json",
            R"({"entry":"Open","limits":{"timeout_ms":3000,"poll_ms":50,"max_transitions":10,"max_recoveries":2},"nodes":{"Open":{"recognition":{"type":"Template","template":"open","threshold":0.95},"action":{"type":"Click"},"next":["Ready"],"on_error":["Ready"],"timeout_ms":1000},"Ready":{"recognition":{"type":"Template","template":"ready","threshold":0.95},"action":{"type":"None"},"timeout_ms":1000}}})");
        write(
            L"replay.json",
            R"({"schema_version":1,"steps":[{"image":"before.png","expect":{"type":"Click","target":[320,180]},"action_delay_ms":20},{"image":"after.png"}]})");
        write(
            L"replay-uncertain.json",
            R"({"schema_version":1,"steps":[{"image":"before.png","expect":{"type":"Click","target":[320,180]},"action_error":"offline"},{"image":"after.png"}]})");
        write(
            L"replay-disconnected.json",
            R"({"schema_version":1,"steps":[{"image":"before.png","capture_error":"offline","expect":{"type":"Click","target":[320,180]}},{"image":"after.png"}]})");
        return {};
    } catch (const std::exception &e) {
        return ar::core::failure(ar::core::ErrorCode::io_failed, "demo", e.what());
    }
}
} // namespace ar::examples
